style_id = #{styleId}, school_name = #{schoolName}, campus_name = #{campusName}, grade_name = #{gradeName}, class_name = #{className}, student_name = #{studentName}, student_no = #{studentNo}, gender = #{gender}, height_value = #{heightValue}, weight_value = #{weightValue}, source_channel = #{sourceChannel}, measure_time = #{measureTime}, recommended_size_code = #{recommendedSizeCode}, recommended_size_name = #{recommendedSizeName}, final_size_code = #{finalSizeCode}, final_size_name = #{finalSizeName}, measure_status = #{measureStatus}, body_remark = #{bodyRemark}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
